/// The items below are pub(crate).
/// One editable field of the settings window.
#[derive(Clone, Debug, PartialEq, Eq)]
struct SettingsField {
    pub key: &'static str,
    pub label: &'static str,
    pub value: String,
}

/// The items below are pub(crate).
/// fallback_encoding and the five document fields, in the TOML order.
fn settings_fields(config: &kate_core::EditorConfig) -> Vec<SettingsField>
/// The config with `key` set to `value`, or the error sentence.
fn apply_setting(config: &kate_core::EditorConfig, key: &str, value: &str) -> Result<kate_core::EditorConfig, String>
